"""Schema-driven generator of tricky table sets (production port of prototype gen_data.py).

  generate(schema, size, seed, lits) -> table-set dict
  harvest(texts) -> literal pools taken from MiniVM program texts

Respects every constraint (key, not_null, refs, check, sorted). Uses stats only to
pick realistic ranges/vocabularies so filters hit. Mixes in NULLs, duplicates and
ties, empty and 1-row tables, case/space variants, weird Unicode (ß, ﬁ, emoji,
combining marks), NUM scale variants (1.0 vs 1.00), zeros (to make DIV error),
boundary dates, and the programs' own literals with +-1 neighbours.
"""
import datetime
import random
import re
from decimal import Decimal

SIZES = {"small": (0, 6), "medium": (20, 150), "large": (600, 2500)}
WEIRD = ["", " ", "  ", "ß", "straße", "Zoë", "e\u0301", "ﬁx", "İ", "ı", "🙂", "it's", "a,b", ";x",
         "NULL", "null", "\t", "ǅ", "x" * 45, "Ünïcødé ✓", "  lead", "trail  ", "1.0", "1.00", "2024-01-01"]
SPECIAL_DATES = ["2022-12-31", "2023-01-01", "2023-01-02", "2023-06-30", "2023-07-01", "2023-07-31",
                 "2023-08-01", "2023-12-31", "2024-01-01", "2024-02-29", "2024-12-31", "0001-01-01", "9999-12-31"]
INT32 = (-2**31, 2**31 - 1)
_STR_LIT = re.compile(r"'((?:[^']|'')*)'")


def strip_comment(line):
    out, q = [], False
    for ch in line:
        if ch == "'":
            q = not q
        if ch == ";" and not q:
            break
        out.append(ch)
    return "".join(out)


def harvest(texts):
    lit = {"STR": set(), "INT": set(), "NUM": set(), "DATE": set()}
    for text in texts:
        for line in text.splitlines():
            code = strip_comment(line)
            for s in _STR_LIT.findall(code):
                lit["STR"].add(s.replace("''", "'"))
            for d in re.findall(r"#(\d{4}-\d{2}-\d{2})#", code):
                lit["DATE"].add(d)
            ops = code.split(None, 1)
            if len(ops) == 2 and not re.match(r"(?i)(left|substr|slice|topk)$", ops[0]):
                rest = _STR_LIT.sub("''", ops[1])
                for n in re.findall(r"(?<![\w.#'])-?\d+(?:\.\d+)?(?![\w.#-])", rest):
                    lit["NUM" if "." in n else "INT"].add(n)
    return {k: sorted(v) for k, v in lit.items()}


def _variants(s, rng):
    return rng.choice([s, s, s.upper(), s.capitalize(), s + " ", s.upper() + "  ", " " + s, s.lower()])


def _rand_word(rng):
    alphabet = "abcdefghijklmnopqrstuvwxyzABC _-'é"
    return "".join(rng.choice(alphabet) for _ in range(rng.randint(0, 12)))


def _isnum(v):
    if isinstance(v, bool):
        return False
    if isinstance(v, int):
        return True
    try:
        Decimal(v)
        return v.strip() != "" and v.strip().lower() not in ("nan", "inf", "infinity", "-inf")
    except Exception:
        return False


def _canon(v):
    return str(Decimal(v).normalize()) if isinstance(v, (int, str)) and _isnum(v) else v


class Gen:
    def __init__(self, schema, size, seed, lits=None):
        self.s, self.rng, self.size = schema, random.Random(seed), size
        self.lit = lits or {"STR": [], "INT": [], "NUM": [], "DATE": []}
        self.data = {}

    def bounds(self, tname, cname):
        chk = {k.lower(): v for k, v in self.s[tname].get("check", {}).items()}
        return chk.get(cname.lower(), [None, None])

    def stats(self, tname, cname):
        cols = self.s[tname].get("stats", {}).get("columns", {})
        for k, v in cols.items():
            if k.lower() == cname.lower():
                return v
        return {}

    def gen_value(self, tname, col, pool):
        rng, typ = self.rng, col["type"]
        if pool and rng.random() < 0.45:
            return rng.choice(pool)
        lo, hi = self.bounds(tname, col["name"])
        st = self.stats(tname, col["name"])
        if typ == "INT":
            a = int(Decimal(str(st["min"]))) if st.get("min") is not None else 0
            b = int(Decimal(str(st["max"]))) if st.get("max") is not None else 100
            span = max(3, b - a)
            a, b = a - span // 3, b + span // 3
            if lo is not None:
                a = max(a, int(Decimal(str(lo)).to_integral_value("ROUND_CEILING")))
            if hi is not None:
                b = min(b, int(Decimal(str(hi)).to_integral_value("ROUND_FLOOR")))
            a, b = max(a, INT32[0]), min(b, INT32[1])
            edges = [int(Decimal(str(x))) for x in (lo, hi) if x is not None] + [0, 1, -1]
            edges += [int(Decimal(x)) + dx for x in self.lit["INT"] + self.lit["NUM"] for dx in (-1, 0, 1)]
            edges = [e for e in edges if (lo is None or e >= Decimal(str(lo))) and (hi is None or e <= Decimal(str(hi)))
                     and INT32[0] <= e <= INT32[1]]
            if edges and rng.random() < 0.25:
                return rng.choice(edges)
            return rng.randint(a, max(a, b))
        if typ == "NUM":
            a = Decimal(str(st["min"])) if st.get("min") is not None else Decimal(0)
            b = Decimal(str(st["max"])) if st.get("max") is not None else Decimal(100)
            span = max(Decimal(1), b - a)
            a, b = a - span / 3, b + span / 3
            if lo is not None:
                a = max(a, Decimal(str(lo)))
            if hi is not None:
                b = min(b, Decimal(str(hi)))
            edges = [Decimal(str(x)) for x in (lo, hi) if x is not None] + [Decimal("0"), Decimal("0.0")]
            edges += [Decimal(x) + dx for x in self.lit["NUM"] + self.lit["INT"]
                      for dx in (Decimal("-0.01"), 0, Decimal("0.01"))]
            edges = [e for e in edges if (lo is None or e >= Decimal(str(lo))) and (hi is None or e <= Decimal(str(hi)))]
            if edges and rng.random() < 0.25:
                v = rng.choice(edges)
                if rng.random() < 0.3:
                    v = v.quantize(Decimal("0.001")) if abs(v) < 10**20 else v   # same value, other scale
            else:
                v = a + (b - a) * Decimal(rng.random())
                scale = rng.choice([0, 1, 2, 2, 3])
                v = v.quantize(Decimal(1).scaleb(-scale), rounding="ROUND_DOWN")
                if v < a:
                    v = a
                if v > b:
                    v = b
            return f"{v:f}"
        if typ == "DATE":
            lits = []
            for x in self.lit["DATE"]:
                for dx in (-1, 0, 1):
                    try:
                        lits.append((datetime.date.fromisoformat(x) + datetime.timedelta(days=dx)).isoformat())
                    except (ValueError, OverflowError):
                        pass
            if rng.random() < 0.3:
                cand = rng.choice(SPECIAL_DATES + lits)
            else:
                d0 = datetime.date.fromisoformat(st.get("min") or "2023-01-01")
                d1 = datetime.date.fromisoformat(st.get("max") or "2024-12-31")
                try:
                    d0, d1 = d0 - datetime.timedelta(days=200), d1 + datetime.timedelta(days=200)
                except OverflowError:
                    pass
                cand = (d0 + datetime.timedelta(days=rng.randint(0, max(0, (d1 - d0).days)))).isoformat()
            if lo is not None and cand < str(lo):
                cand = str(lo)
            if hi is not None and cand > str(hi):
                cand = str(hi)
            return cand
        vocab = [v for v, _ in st.get("common", [])] + [x for x in (st.get("min"), st.get("max")) if x]
        r = rng.random()
        if self.lit["STR"] and r < 0.25:
            return _variants(rng.choice(self.lit["STR"]).lower(), rng)
        if vocab and r < 0.6:
            return _variants(rng.choice(vocab), rng)
        if r < 0.8:
            return rng.choice(WEIRD)
        return _rand_word(rng)

    def order(self):
        deps = {t: {v.split(".")[0] for v in self.s[t].get("refs", {}).values()} - {t} for t in self.s}
        lower = {t.lower(): t for t in self.s}
        deps = {t: {lower.get(d.lower(), d) for d in ds} for t, ds in deps.items()}
        done, out = set(), []
        while len(out) < len(self.s):
            progress = False
            for t in self.s:
                if t not in done and deps[t] <= done:
                    done.add(t)
                    out.append(t)
                    progress = True
            if not progress:          # cyclic refs: emit the rest in any order
                out += [t for t in self.s if t not in done]
                break
        return out

    def nrows(self, t):
        lo, hi = SIZES[self.size]
        if self.size == "small" and self.rng.random() < 0.25:
            return self.rng.choice([0, 1])
        n = self.rng.randint(lo, hi)
        return n * 3 if self.s[t].get("refs") and self.size != "small" else n

    def gen_table(self, t):
        rng, spec = self.rng, self.s[t]
        cols = spec["columns"]
        names = [c["name"].lower() for c in cols]
        key = [k.lower() for k in spec.get("key", [])]
        nn = set(key) | {c.lower() for c in spec.get("not_null", [])}
        refs = {k.lower(): v for k, v in spec.get("refs", {}).items()}
        pools = {c["name"].lower(): [self.gen_value(t, c, None) for _ in range(rng.randint(1, 4))] for c in cols}
        n = self.nrows(t)
        lower = {x.lower(): x for x in self.s}
        parents = {}
        for c, target in refs.items():
            pt, pc = target.split(".")
            pt = lower[pt.lower()]
            if pt != t:
                pnames = [x["name"].lower() for x in self.s[pt]["columns"]]
                pv = [r[pnames.index(pc.lower())] for r in self.data[pt]["rows"]]
                parents[c] = pv
                if not pv and c in nn:
                    n = 0
        rows = []
        for _ in range(n):
            row = []
            for c, cname in zip(cols, names):
                if cname in parents:
                    pv = parents[cname]
                    row.append(None if (cname not in nn and rng.random() < 0.15) or not pv else rng.choice(pv))
                elif cname not in nn and rng.random() < 0.15:
                    row.append(None)
                elif len(key) == 1 and cname == key[0] and c["type"] == "INT":
                    row.append(None)
                else:
                    row.append(self.gen_value(t, c, pools[cname]))
            rows.append(row)
        if len(key) == 1:
            ki = names.index(key[0])
            if cols[ki]["type"] == "INT":
                lo, hi = self.bounds(t, key[0])
                base = int(Decimal(str(lo))) if lo is not None else rng.choice([1, 10, 1001])
                ids = list(range(base, base + 2 * max(1, len(rows))))
                if hi is not None:
                    ids = [i for i in ids if i <= Decimal(str(hi))]
                rng.shuffle(ids)
                rows = rows[:len(ids)]
                for r, v in zip(rows, ids):
                    r[ki] = v
        if key:
            kis = [names.index(k) for k in key]
            seen, uniq = set(), []
            for r in rows:
                kt = tuple(_canon(r[i]) for i in kis)
                if None in kt or kt in seen:
                    continue
                seen.add(kt)
                uniq.append(r)
            rows = uniq
        for c, target in refs.items():
            pt, pc = target.split(".")
            if lower[pt.lower()] == t:
                ci, pi = names.index(c), names.index(pc.lower())
                pv = [r[pi] for r in rows]
                for r in rows:
                    r[ci] = None if (c not in nn and rng.random() < 0.4) or not pv else rng.choice(pv)
        if spec.get("sorted"):
            sis = [names.index(c.lower()) for c in spec["sorted"]]
            types = {i: c["type"] for i, c in enumerate(cols)}

            def sk(r):
                out = []
                for i in sis:
                    v = r[i]
                    if v is None:
                        out.append((0, 0))
                    elif types[i] in ("INT", "NUM"):
                        out.append((1, Decimal(str(v))))
                    elif types[i] == "STR":
                        out.append((1, v.encode()))
                    else:
                        out.append((1, v))
                return out
            rows.sort(key=sk)
        tbl = {"columns": cols, "rows": rows}
        for k in ("key", "not_null", "refs", "check", "sorted"):
            if k in spec:
                tbl[k] = spec[k]
        self.data[t] = tbl

    def run(self):
        for t in self.order():
            self.gen_table(t)
        return self.data


def generate(schema, size, seed, lits=None):
    return Gen(schema, size, seed, lits).run()

"""Comparator for ./evaluate: is the optimized result the same as the original's?

Independent of optimizer/: its own parser and analyses.

Rules (BUILD_PLAN §6):
  O1 ncols equal; the optimized program must succeed whenever the original does
  O2 rows in order if the original specifies order (a SORT/TOPK reaches OUT), else multiset
     - rows tied on the sort keys may come in any order (compared as a multiset per tie block)
     - at a TOPK/SLICE cut-off, a different choice among tied rows is a WARN, not a defect
  O3 numbers (INT/NUM printed as -?\\d+(\\.\\d+)?) agree within 1e-6 relative
  O4 STR/DATE exact (output types inferred statically from the original); BOOL never equals INT
"""
import json
import re
from collections import Counter
from decimal import Decimal

KEYWORDS = {"NULL", "TRUE", "FALSE", "ASC", "DESC", "NF", "NL", "NULLEQ"}
REL_TOL = Decimal("1e-6")
NUM_TEXT = re.compile(r"-?\d+(\.\d+)?")
ELEMENTWISE = {"ADD", "SUB", "MUL", "DIV", "IDIV", "MOD", "NEG", "WRAP", "TRUNC", "EQ", "NE", "LT", "LE", "GT",
               "GE", "IS", "AND", "OR", "NOT", "ISNULL", "NVL", "IF", "NULLIF", "NULLIFE", "UPPER", "RTRIM", "TRIM",
               "LEFT", "SUBSTR", "LEN", "CAT", "YEAR", "MONTH", "DAY", "DOW", "DATEADD", "DATEDIFF"}


# ---------------------------------------------------------------- parsing
def parse(text):
    prog = []
    for line in text.splitlines():
        code, q = [], False
        for ch in line:
            if ch == "'":
                q = not q
            if ch == ";" and not q:
                break
            code.append(ch)
        code = "".join(code).strip()
        if not code:
            continue
        parts = code.split(None, 1)
        ops, cur, q = [], [], False
        for ch in parts[1] if len(parts) > 1 else "":
            if ch == "'":
                q = not q
            if ch == "," and not q:
                ops.append("".join(cur).strip())
                cur = []
            else:
                cur.append(ch)
        if "".join(cur).strip():
            ops.append("".join(cur).strip())
        prog.append((parts[0].upper(), ops))
    return prog


def reg(tok):
    t = tok.split()[0] if tok.split() else ""
    if not t or not (t[0].isalpha() or t[0] == "_") or not all(c.isalnum() or c == "_" for c in t):
        return None
    return None if t.upper() in KEYWORDS else t


def lit_type(tok):
    t = tok.strip()
    if t.startswith("'"):
        return "STR"
    if t.startswith("#"):
        return "DATE"
    if t.upper() in ("TRUE", "FALSE"):
        return "BOOL"
    if t.upper() == "NULL":
        return None
    return "NUM" if "." in t else "INT"


# ---------------------------------------------------------------- does the original specify order?
def output_ordered(prog):
    ordered, mono = set(), set()
    o = lambda t: reg(t) in ordered
    for op, a in prog:
        if op == "OUT":
            return any(o(t) for t in a)
        if op in ("HJOIN", "NLJOIN"):
            li, ri, lk = a[0], a[1], a[2]
            for d in (li, ri):
                ordered.discard(d)
                mono.discard(d)
            if o(lk):
                ordered.update({li, ri})
            if li != ri:
                mono.add(li)
            continue
        if not a:
            continue
        d, src = a[0], a[1:]
        if op in ("SORT", "TOPK"):
            is_o, is_m = True, False
        elif op == "GATHER" and len(src) >= 2:
            s, i = reg(src[0]), reg(src[1])
            is_o = i in ordered or (s in ordered and i in mono)
            is_m = s in mono and i in mono
        elif op == "LOAD":
            is_o, is_m = False, False
        elif op in ("IDX", "GFIRST"):
            is_o, is_m = (op == "GFIRST" and bool(src) and o(src[0])), True
        elif op == "IOTA":
            is_o, is_m = bool(src) and o(src[0]), True
        elif op == "SLICE":
            is_o, is_m = bool(src) and o(src[0]), bool(src) and reg(src[0]) in mono
        else:
            is_o, is_m = any(o(t) for t in src), False
        ordered.discard(d)
        mono.discard(d)
        if is_o:
            ordered.add(d)
        if is_m:
            mono.add(d)
    return False


# ---------------------------------------------------------------- static output types
def out_types(prog, schema):
    cols = {}
    for t, spec in schema.items():
        for c in spec["columns"]:
            cols[f"{t}.{c['name']}".lower()] = c["type"]
    ty = {}

    def tof(tok):
        r = reg(tok)
        return ty.get(r) if r else lit_type(tok)

    for op, a in prog:
        if op == "OUT":
            return [tof(t) for t in a]
        if not a:
            continue
        d, src = a[0], a[1:]
        t = None
        if op == "LOAD":
            t = cols.get(src[0].lower()) if src else None
        elif op in ("ADD", "SUB", "MUL"):
            ts = {tof(x) for x in src}
            t = "INT" if ts == {"INT"} else ("NUM" if ts <= {"INT", "NUM", None} else None)
        elif op == "NEG":
            t = tof(src[0])
        elif op in ("DIV",):
            t = "NUM"
        elif op in ("IDIV", "MOD", "WRAP", "TRUNC", "LEN", "YEAR", "MONTH", "DAY", "DOW", "DATEDIFF", "IDX", "IOTA",
                    "SORT", "TOPK", "GID", "GFIRST", "GCOUNT", "GCOUNTV"):
            t = "INT"
        elif op in ("EQ", "NE", "LT", "LE", "GT", "GE", "IS", "AND", "OR", "NOT", "ISNULL"):
            t = "BOOL"
        elif op in ("UPPER", "RTRIM", "TRIM", "LEFT", "SUBSTR", "CAT", "NULLIFE"):
            t = "STR"
        elif op == "DATEADD":
            t = "DATE"
        elif op in ("NVL",):
            ts = {tof(x) for x in src} - {None}
            t = ts.pop() if len(ts) == 1 else None
        elif op == "IF":
            ts = {tof(x) for x in src[1:]} - {None}
            t = ts.pop() if len(ts) == 1 else None
        elif op == "NULLIF":
            t = tof(src[0])
        elif op in ("GATHER", "SLICE"):
            t = tof(src[0])
        elif op == "FILL":
            t = lit_type(src[0])
        elif op in ("GMIN", "GMAX"):
            t = tof(src[1]) if len(src) > 1 else None
        elif op == "GSUM":
            t = tof(src[1]) if len(src) > 1 else None
        if op in ("HJOIN", "NLJOIN"):
            ty[a[0]] = ty[a[1]] = "INT"
            continue
        ty[d] = t
    return []


# ---------------------------------------------------------------- tie keys by instrumenting the original
def instrument(prog):
    """Return a program text whose OUT has the original columns followed by the sort keys
    (of every SORT/TOPK that orders the output, latest first), or None if they can't be traced."""
    # SSA-rename so overwrites can't confuse the path search
    ver, ssa = {}, []

    def use(tok):
        r = reg(tok)
        if r is None:
            return tok
        rest = tok.split(None, 1)
        name = f"{r}__{ver.get(r, 0)}"
        return name + (" " + rest[1] if len(rest) > 1 else "")

    def define(r):
        ver[r] = ver.get(r, 0) + 1
        return f"{r}__{ver[r]}"

    for op, a in prog:
        if op == "OUT":
            ssa.append((op, [use(t) for t in a]))
            break
        if op in ("HJOIN", "NLJOIN"):
            srcs = [use(t) for t in a[2:]]
            if a[0] == a[1]:
                d = define(a[0])
                ssa.append((op, [d, d] + srcs))
            else:
                ssa.append((op, [define(a[0]), define(a[1])] + srcs))
            continue
        if op == "LOAD":
            ssa.append((op, [define(a[0])] + a[1:]))
            continue
        srcs = [use(t) for t in a[1:]]
        ssa.append((op, [define(a[0])] + srcs))
    if not ssa or ssa[-1][0] != "OUT":
        return None

    dom, into = {}, {}      # register -> domain id ; position register -> domain it points into
    edges = {}              # domain -> list of (position register, target domain)
    sorts = []              # (index, sorted-rows domain, [(key reg, positions reg)])
    gsets = {}              # group set reg -> (key domain, group domain)
    extra = []              # helper instructions appended before OUT
    n = [0]

    def fresh():
        n[0] += 1
        return f"__t{n[0]}"

    def new_dom():
        n[0] += 1
        return f"D{n[0]}"

    def add_edge(p, frm, to):
        into[p] = to
        edges.setdefault(frm, []).append((p, to))

    for idx, (op, a) in enumerate(ssa[:-1]):
        d, src = a[0], a[1:]
        regs = [reg(t) for t in src if reg(t)]
        if op == "LOAD":
            dom[d] = "T:" + src[0].split(".")[0].lower()
        elif op in ELEMENTWISE or op == "FILL":
            dom[d] = next((dom.get(r) for r in regs if r in dom), None)
        elif op == "IOTA":
            dom[d] = dom.get(regs[0]) if regs else None
            if dom[d]:
                add_edge(d, dom[d], dom[d])
        elif op == "IDX":
            nd = new_dom()
            dom[d] = nd
            if regs and dom.get(regs[0]):
                add_edge(d, nd, dom[regs[0]])
        elif op in ("SORT", "TOPK"):
            nd = new_dom()
            dom[d] = nd
            keys = [reg(t) for t in (src[1:] if op == "TOPK" else src)]
            kd = dom.get(keys[0]) if keys and keys[0] else None
            if kd:
                add_edge(d, nd, kd)
                sorts.append((idx, nd, [(k, d) for k in keys if k]))
        elif op == "GATHER":
            s, i = regs[0], regs[1] if len(regs) > 1 else None
            dom[d] = dom.get(i)
            if s in into and dom[d]:
                add_edge(d, dom[d], into[s])
        elif op == "SLICE":
            nd = new_dom()
            dom[d] = nd
            s = regs[0] if regs else None
            if s in into:
                into[d] = into[s]
                edges.setdefault(nd, []).append((d, into[s]))
            elif s in dom:
                t1, t2 = fresh(), fresh()
                extra += [("IOTA", [t1, s]), ("SLICE", [t2, t1, src[1]])]
                add_edge(t2, nd, dom[s])
        elif op in ("HJOIN", "NLJOIN"):
            nd = new_dom()
            lk, rk = reg(a[2]), reg(a[3])
            if a[0] == a[1]:
                dom[d] = nd
                if dom.get(rk):
                    add_edge(d, nd, dom[rk])
            else:
                dom[a[0]] = dom[a[1]] = nd
                if dom.get(lk):
                    add_edge(a[0], nd, dom[lk])
                if dom.get(rk):
                    add_edge(a[1], nd, dom[rk])
        elif op in ("GROUP", "GALL"):
            gsets[d] = (dom.get(regs[0]) if regs else None, new_dom())
        elif op in ("GCOUNT", "GCOUNTV", "GSUM", "GMIN", "GMAX", "GFIRST"):
            g = regs[0] if regs else None
            kd, gd = gsets.get(g, (None, None))
            dom[d] = gd
            if op == "GFIRST" and kd:
                add_edge(d, gd, kd)
            elif gd and kd and not any(t == kd for _, t in edges.get(gd, [])):
                t = fresh()
                extra.append(("GFIRST", [t, g]))
                add_edge(t, gd, kd)
        elif op == "GID":
            g = regs[0] if regs else None
            kd, gd = gsets.get(g, (None, None))
            dom[d] = kd
            if kd and gd:
                add_edge(d, kd, gd)
        else:
            dom[d] = None

    outs = ssa[-1][1]
    od = dom.get(reg(outs[0])) if outs else None
    if od is None or not sorts:
        return None
    # BFS from the output domain; remember a composed position register per reached domain
    reach = {od: None}
    queue = [od]
    while queue:
        cur = queue.pop(0)
        for p, to in edges.get(cur, []):
            if to in reach:
                continue
            path = reach[cur]
            if path is None:
                reach[to] = p
            else:
                t = fresh()
                extra.append(("GATHER", [t, p, path]))
                reach[to] = t
            queue.append(to)
    keycols = []
    for _, sd, keys in sorted(sorts, key=lambda s: -s[0]):
        if sd not in reach:
            continue
        for k, p in keys:
            kv = fresh()
            extra.append(("GATHER", [kv, k, p]))          # key value in sorted-rows order
            if reach[sd] is None:
                keycols.append(kv)
            else:
                t = fresh()
                extra.append(("GATHER", [t, kv, reach[sd]]))
                keycols.append(t)
    if not keycols:
        return None
    body = ssa[:-1] + extra + [("OUT", outs + keycols)]
    return "\n".join(f"{op} {', '.join(a)}" for op, a in body) + "\n"


# ---------------------------------------------------------------- value comparison
def num(v):
    if isinstance(v, bool) or v is None:
        return None
    if isinstance(v, int):
        return Decimal(v)
    if isinstance(v, str) and NUM_TEXT.fullmatch(v):
        return Decimal(v)
    return None


def close(a, b, t=None):
    if isinstance(a, bool) or isinstance(b, bool):
        return type(a) is type(b) and a == b
    if a == b:
        return True
    if t in ("STR", "DATE"):
        return False
    na, nb = num(a), num(b)
    if na is None or nb is None:
        return False
    return na == nb or abs(na - nb) <= REL_TOL * max(abs(na), abs(nb))


def canon(v, t=None):
    if t not in ("STR", "DATE"):
        n = num(v)
        if n is not None:
            return (1, str(n.normalize()))
    return (0, json.dumps(v, ensure_ascii=False))


def row_close(x, y, types):
    return len(x) == len(y) and all(close(p, q, types[i] if i < len(types) else None) for i, (p, q) in enumerate(zip(x, y)))


def same_multiset(ra, rb, types):
    if len(ra) != len(rb):
        return False
    key = lambda r: tuple(canon(v, types[i] if i < len(types) else None) for i, v in enumerate(r))
    if Counter(map(key, ra)) == Counter(map(key, rb)):
        return True
    sa, sb = sorted(ra, key=key), sorted(rb, key=key)
    if all(row_close(x, y, types) for x, y in zip(sa, sb)):
        return True
    if len(ra) > 3000:
        return False
    unused = list(rb)
    for x in ra:
        for i, y in enumerate(unused):
            if row_close(x, y, types):
                del unused[i]
                break
        else:
            return False
    return True


def tie_blocks(keys):
    """Split row indexes into runs of equal sort keys (NULL == NULL, numbers by value)."""
    blocks, prev = [], object()
    for i, k in enumerate(keys):
        ck = tuple(canon(v) for v in k)
        if ck != prev:
            blocks.append([])
            prev = ck
        blocks[-1].append(i)
    return blocks


def compare(orig, opt, ordered, types, keyed=None, cutoff=False):
    """orig/opt: VM result dicts. keyed: the instrumented original's rows (cols + keys) or None.
    -> (status, detail) with status OK | WARN | DEFECT."""
    if orig["ncols"] != opt["ncols"]:
        return "DEFECT", f"ncols {orig['ncols']} vs {opt['ncols']}"
    ra, rb = orig["rows"], opt["rows"]
    if not same_multiset(ra, rb, types):
        if ordered and cutoff and keyed is not None and len(ra) == len(rb):
            nc = orig["ncols"]
            blocks = tie_blocks([r[nc:] for r in keyed])
            if blocks and all(same_multiset([ra[i] for i in b], [rb[i] for i in b], types) for b in blocks[:-1]):
                return "WARN", "differs only among rows tied at a TOPK/SLICE cut-off"
        return "DEFECT", f"rows differ ({len(ra)} vs {len(rb)} rows)"
    if not ordered:
        return "OK", ""
    if all(row_close(x, y, types) for x, y in zip(ra, rb)):
        return "OK", ""
    if keyed is not None and len(keyed) == len(ra):
        nc = orig["ncols"]
        blocks = tie_blocks([r[nc:] for r in keyed])
        if all(same_multiset([ra[i] for i in b], [rb[i] for i in b], types) for b in blocks):
            return "OK", "tied rows reordered"
    return "DEFECT", "same rows but different order (the original specifies order)"

